package detector

import (
	"encoding/json"
	"net/http"
	"time"

	"github.com/cenkalti/backoff"
	"github.com/parnurzeal/gorequest"
	"golang.org/x/xerrors"

	"github.com/future-architect/vuls/config"
	"github.com/future-architect/vuls/logging"
	"github.com/future-architect/vuls/models"
	"github.com/future-architect/vuls/util"
	kevulndb "github.com/vulsio/go-kev/db"
	kevulnmodels "github.com/vulsio/go-kev/models"
	kevulnlog "github.com/vulsio/go-kev/utils"
)

// goKEVulnDBClient is a DB Driver
type goKEVulnDBClient struct {
	driver  kevulndb.DB
	baseURL string
}

// closeDB close a DB connection
func (client goKEVulnDBClient) closeDB() error {
	if client.driver == nil {
		return nil
	}
	return client.driver.CloseDB()
}

func newGoKEVulnDBClient(cnf config.VulnDictInterface, o logging.LogOpts) (*goKEVulnDBClient, error) {
	if err := kevulnlog.SetLogger(o.LogToFile, o.LogDir, o.Debug, o.LogJSON); err != nil {
		return nil, xerrors.Errorf("Failed to set go-kev logger. err: %w", err)
	}

	db, err := newKEVulnDB(cnf)
	if err != nil {
		return nil, xerrors.Errorf("Failed to newKEVulnDB. err: %w", err)
	}
	return &goKEVulnDBClient{driver: db, baseURL: cnf.GetURL()}, nil
}

// FillWithKEVuln :
func FillWithKEVuln(r *models.ScanResult, cnf config.KEVulnConf, logOpts logging.LogOpts) error {
	client, err := newGoKEVulnDBClient(&cnf, logOpts)
	if err != nil {
		return err
	}
	defer func() {
		if err := client.closeDB(); err != nil {
			logging.Log.Errorf("Failed to close DB. err: %+v", err)
		}
	}()

	kevsByCVE := make(map[string][]models.KEV, len(r.ScannedCves))
	if client.driver == nil {
		var cveIDs []string
		for cveID := range r.ScannedCves {
			cveIDs = append(cveIDs, cveID)
		}
		prefix, err := util.URLPathJoin(client.baseURL, "cves")
		if err != nil {
			return err
		}
		responses, err := getKEVulnsViaHTTP(cveIDs, prefix)
		if err != nil {
			return err
		}
		for _, res := range responses {
			response, err := decodeKEVulnResponse(res.json)
			if err != nil {
				return err
			}
			kevsByCVE[res.request.cveID] = convertKEVulns(response.CISA, response.VulnCheck)
		}
	} else {
		for cveID := range r.ScannedCves {
			if cveID == "" {
				continue
			}
			response, err := client.driver.GetKEVByCveID(cveID)
			if err != nil {
				return err
			}
			kevsByCVE[cveID] = convertKEVulns(response.CISA, response.VulnCheck)
		}
	}

	nKEV := 0
	for cveID, vuln := range r.ScannedCves {
		vuln.KEVs = kevsByCVE[cveID]
		if len(vuln.KEVs) != 0 {
			nKEV++
		}
		r.ScannedCves[cveID] = vuln
	}

	logging.Log.Infof("%s: Known Exploited Vulnerabilities are detected for %d CVEs", r.FormatServerName(), nKEV)
	return nil
}

// decodeKEVulnResponse accepts the combined response and the older CISA-only
// array returned by previous versions of go-kev's HTTP API.
func decodeKEVulnResponse(body string) (kevulndb.Response, error) {
	var response kevulndb.Response
	if err := json.Unmarshal([]byte(body), &response); err == nil {
		return response, nil
	}
	var cisa []kevulnmodels.KEVuln
	if err := json.Unmarshal([]byte(body), &cisa); err != nil {
		return kevulndb.Response{}, err
	}
	return kevulndb.Response{CISA: cisa}, nil
}

func convertKEVulns(cisa []kevulnmodels.KEVuln, vulncheck []kevulnmodels.VulnCheck) []models.KEV {
	kevs := make([]models.KEV, 0, len(cisa)+len(vulncheck))
	for _, record := range cisa {
		kevs = append(kevs, models.KEV{
			Type:                       models.CISAKEVType,
			VendorProject:              record.VendorProject,
			Product:                    record.Product,
			VulnerabilityName:          record.VulnerabilityName,
			ShortDescription:           record.ShortDescription,
			RequiredAction:             record.RequiredAction,
			KnownRansomwareCampaignUse: record.KnownRansomwareCampaignUse,
			DateAdded:                  record.DateAdded,
			DueDate:                    validKEVDueDate(&record.DueDate),
			CISA:                       &models.CISAKEV{Note: record.Notes},
		})
	}
	for _, record := range vulncheck {
		details := &models.VulnCheckKEV{
			XDB:                  make([]models.VulnCheckXDB, 0, len(record.VulnCheckXDB)),
			ReportedExploitation: make([]models.VulnCheckReportedExploitation, 0, len(record.VulnCheckReportedExploitation)),
		}
		for _, xdb := range record.VulnCheckXDB {
			details.XDB = append(details.XDB, models.VulnCheckXDB{
				XDBID:       xdb.XDBID,
				XDBURL:      xdb.XDBURL,
				DateAdded:   xdb.DateAdded,
				ExploitType: xdb.ExploitType,
				CloneSSHURL: xdb.CloneSSHURL,
			})
		}
		for _, exploitation := range record.VulnCheckReportedExploitation {
			details.ReportedExploitation = append(details.ReportedExploitation, models.VulnCheckReportedExploitation{
				URL:       exploitation.URL,
				DateAdded: exploitation.DateAdded,
			})
		}
		kevs = append(kevs, models.KEV{
			Type:                       models.VulnCheckKEVType,
			VendorProject:              record.VendorProject,
			Product:                    record.Product,
			VulnerabilityName:          record.Name,
			ShortDescription:           record.Description,
			RequiredAction:             record.RequiredAction,
			KnownRansomwareCampaignUse: record.KnownRansomwareCampaignUse,
			DateAdded:                  record.DateAdded,
			DueDate:                    validKEVDueDate(record.DueDate),
			VulnCheck:                  details,
		})
	}
	return kevs
}

func validKEVDueDate(date *time.Time) *time.Time {
	if date == nil || date.Year() <= 1 {
		return nil
	}
	dueDate := *date
	return &dueDate
}

type kevulnResponse struct {
	request kevulnRequest
	json    string
}

func getKEVulnsViaHTTP(cveIDs []string, urlPrefix string) (
	responses []kevulnResponse, err error) {
	nReq := len(cveIDs)
	reqChan := make(chan kevulnRequest, nReq)
	resChan := make(chan kevulnResponse, nReq)
	errChan := make(chan error, nReq)
	defer close(reqChan)
	defer close(resChan)
	defer close(errChan)

	go func() {
		for _, cveID := range cveIDs {
			reqChan <- kevulnRequest{
				cveID: cveID,
			}
		}
	}()

	concurrency := 10
	tasks := util.GenWorkers(concurrency)
	for i := 0; i < nReq; i++ {
		tasks <- func() {
			req := <-reqChan
			url, err := util.URLPathJoin(
				urlPrefix,
				req.cveID,
			)
			if err != nil {
				errChan <- err
			} else {
				logging.Log.Debugf("HTTP Request to %s", url)
				httpGetKEVuln(url, req, resChan, errChan)
			}
		}
	}

	timeout := time.After(2 * 60 * time.Second)
	var errs []error
	for i := 0; i < nReq; i++ {
		select {
		case res := <-resChan:
			responses = append(responses, res)
		case err := <-errChan:
			errs = append(errs, err)
		case <-timeout:
			return nil, xerrors.New("Timeout Fetching KEVuln")
		}
	}
	if len(errs) != 0 {
		return nil, xerrors.Errorf("Failed to fetch KEVuln. err: %w", errs)
	}
	return
}

type kevulnRequest struct {
	cveID string
}

